begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "5920d312-9541-59c8-aee2-a1e6c21c7766", "feature_slug": "action-macro-shared", "title": "Functions", "content": "| Function | Type | Purpose |\n|---|---|---|\n| `bff_upsert_macro_with_contexts` | BFF | Create/update macro + context bindings (with_children pattern) |\n| `bff_get_macro_details` | BFF | Get macro + contexts (new/edit mode) |\n| `bff_list_macros` | BFF | List macros, optionally filtered by context_type |\n| `bff_delete_macro` | BFF | Delete macro (contexts cascade) |\n| `fn_validate_macro_variables` | Internal | Validate variables against Layer 1 + Layer 2 constraints |\n| `fn_check_macro_approval` | Internal | Check approval thresholds, return approved/requires_approval/blocked |\n| `fn_execute_macro` | Internal | Orchestrate: validate → check approval → resolve variables → dispatch steps |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Action_Macro.md#L129 Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "action-macro-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0787daebaede50e05e53e0773e80bd98cae7f54ed6210399b706ae79c4554a41", "truncated": false}, "is_active": true}, {"id": "093bda89-b781-59b0-8928-698870b1f189", "feature_slug": "action-macro-shared", "title": "Tables", "content": "### `action_macro`\n\nThe macro definition. Shared across all modules — no module-specific prefix.\n\n| Column | Type | Default | Notes |\n|---|---|---|---|\n| `id` | uuid | gen_random_uuid() | PK |\n| `merchant_id` | uuid NOT NULL | — | FK → merchant_master |\n| `macro_code` | text | NULL | Human-readable identifier |\n| `name` | text NOT NULL | — | Display name |\n| `description` | text | NULL | What this macro does |\n| `steps` | jsonb NOT NULL | — | Ordered array of action steps |\n| `variable_definitions` | jsonb NOT NULL | ''{}'' | Schema for variables — the ceiling |\n| `tags` | text[] | ''{}'' | Organizational tags for search |\n| `is_active` | boolean | true | |\n| `sort_order` | integer | 0 | |\n| `created_by` | uuid | NULL | |\n| `created_at` | timestamptz | now() | |\n| `updated_at` | timestamptz | now() | |\n\n### `action_macro_context`\n\nPer-context guardrails. Each row makes a macro available in a specific context with specific variable constraints.\n\n| Column | Type | Default | Notes |\n|---|---|---|---|\n| `id` | uuid | gen_random_uuid() | PK |\n| `merchant_id` | uuid NOT NULL | — | FK → merchant_master |\n| `macro_id` | uuid NOT NULL | — | FK → action_macro (CASCADE) |\n| `context_type` | text NOT NULL | — | `cs_agent`, `cs_ai`, `amp_agent`, `amp_rule` |\n| `context_ref_id` | uuid | NULL | Optional: role_id for cs_agent, agent_id for amp_agent |\n| `variable_constraints` | jsonb NOT NULL | ''{}'' | Per-variable overrides — can only narrow |\n| `requires_approval` | boolean | false | |\n| `approval_threshold` | jsonb | NULL | Conditional approval config |\n| `is_enabled` | boolean | true | |\n| `sort_order` | integer | 0 | |\n| `created_at` | timestamptz | now() | |\n| `updated_at` | timestamptz | now() | |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Action_Macro.md#L7 Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "action-macro-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a360b596861f5533d79e4910ac4c83da9e6d763fca604f8d9f0c872007b143e3", "truncated": false}, "is_active": true}, {"id": "6f268d4c-118b-5723-90e0-702edc1679e5", "feature_slug": "action-macro-shared", "title": "Guardrail Architecture", "content": "Three layers, progressively narrowing:\n\n**Layer 1 — Macro ceiling** (`action_macro.variable_definitions`): Absolute limits. No context can exceed these.\n\n**Layer 2 — Context binding** (`action_macro_context.variable_constraints`): Per-actor narrowing. Can only tighten, never widen.\n\n**Layer 3 — Runtime** (existing per-module systems): AMP budget/frequency constraints, CS merchant guardrails, agent role RBAC.\n\n### Approval Threshold Format\n\n```json\n{\n  \"variable\": \"voucher_amount\",\n  \"auto_approve_max\": 200,\n  \"approval_role\": \"cs_supervisor\",\n  \"blocked_above\": 1000\n}\n```", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Action_Macro.md#L108 Guardrail Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "action-macro-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "424ff413d09c5da761fb6010e31ce27320938f1aed69c791c94ea1a6f6dca15f", "truncated": false}, "is_active": true}, {"id": "8c40b640-e270-5f78-a3a3-57fd1bea89a7", "feature_slug": "action-macro-shared", "title": "Execution Flow", "content": "1. Caller invokes `fn_execute_macro(macro_id, context_type, context_ref_id, user_id, merchant_id, variables, conversation_id)`\n2. `fn_validate_macro_variables` checks Layer 1 + Layer 2 constraints → resolved variables\n3. `fn_check_macro_approval` checks thresholds → approved / requires_approval / blocked\n4. If approved: iterate steps, resolve `{{variable}}` placeholders, dispatch each to handler\n5. Value/classification actions → `fn_execute_amp_action` (existing)\n6. Content actions → insert into `cs_messages` with resource metadata\n7. System actions → update `cs_conversations` / insert notes\n8. Returns step-by-step results summary", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Action_Macro.md#L141 Execution Flow", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "action-macro-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "55b25dc6fc2ad773941e4830beb618fd986744aca35093affd422ea0211ef001", "truncated": false}, "is_active": true}, {"id": "88bb09d8-4949-5738-8a6a-076255a87b63", "feature_slug": "action-macro-shared", "title": "Action Macro (Shared) Domain Reference", "content": "**Keywords:** action_macro, macro, macro_context, execute_macro, multi_step_action, parameterized_action, variable_definitions, variable_constraints, approval_threshold, guardrail, action_sequence\n**Source:** `Action_Macro.md`\n**Tables:** `action_macro`, `action_macro_context`\n| Function | Type | Purpose |\n|---|---|---|\n| `bff_upsert_macro_with_contexts` | BFF | Create/update macro + context bindings |\n| `bff_get_macro_details` | BFF | Get macro + contexts (new/edit mode) |\n| `bff_list_macros` | BFF | List macros, optionally by context_type |\n| `bff_delete_macro` | BFF | Delete macro (contexts cascade) |\n| `fn_validate_macro_variables` | Internal | Validate variables against Layer 1 + Layer 2 constraints |\n| `fn_check_macro_approval` | Internal | Check approval thresholds |\n| `fn_execute_macro` | Internal | Orchestrate macro execution |\n**Key Business Rules (summary):**\n- Shared entity — used by CS Agent, CS AI, AMP AI Agent, AMP Rule-Based\n- Macros define steps + variable definitions (the ceiling)\n- `action_macro_context` binds macros to contexts with narrowed variable constraints\n- Three guardrail layers: macro ceiling → context constraints → runtime (AMP budgets, CS guardrails, RBAC)\n- Approval thresholds: auto-approve below X, require approval X–Y, block above Y\n- Execution routes value/classification actions to `fn_execute_action` (universal dispatcher), content actions to `cs_messages`, system actions to `cs_conversations`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/action-macro-shared.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "action-macro-shared", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f622b724660554b65e9b283a163f6f107414f3702a666ea0e1c9bd67b52f2009", "truncated": false}, "is_active": true}, {"id": "ac85717b-166e-52f1-b527-66735f77c596", "feature_slug": "activity-based-earning", "title": "4. Admin Journey", "content": "### 4a. Activity Configuration (WeWeb Admin)\n\n**Platform:** WeWeb admin dashboard\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Activity Settings | WeWeb activity page | `api_get_activity_full(p_activity_id, p_mode)` |\n| Matrix Editor | Within Activity Settings | `bff_upsert_activity_currency_matrix(p_activity_id, p_matrix_configs)` |\n\n1. Open **Activity Settings** — in create mode (empty) or edit mode (pre-populated)\n2. Fill activity info: code, name, description, icon, banners\n3. Define fields: add manual fields with option lists, add auto_populate fields with profile field key mappings, set one field as primary dimension\n4. Configure currency matrix: a Data Grid renders one table per secondary field, with primary dimension values as columns — enter points and ticket amounts per cell\n5. Save via `bff_upsert_activity_master` (activity + fields) and `bff_upsert_activity_currency_matrix` (matrix cells)\n\n### 4b. Review Uploads (Next.js Admin)\n\n**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Activity Uploads | `/approve-activities-upload` | `bff_get_activity_uploads(p_status_filter, p_activity_id, p_limit, p_offset)` |\n| Review Modal | Modal on Activity Uploads | `bff_approve_activity_upload(p_upload_id, p_field_values)` |\n| Reject Modal | Modal on Activity Uploads | `bff_reject_activity_upload(p_upload_id, p_rejection_reason)` |\n\n1. Open **Activity Uploads** — IndexTable with tabs: All, Pending, Approved, Rejected (each with count)\n2. Search bar filters by member name, phone, email, or activity name\n3. Columns: thumbnail, Member, Activity, Status (badge), Points, Tickets, Date\n4. Click any row → **Review Modal** opens (two-column layout)\n5. Left panel: uploaded image, member name/phone/email, awarded points (if approved), rejection reason (if rejected)\n6. Right panel: activity details + **dynamic field editor** — renders Select dropdowns for manual fields, TextFields for other types\n7. Fill in field values from the image evidence, then click **Approve** → `bff_approve_activity_upload` validates fields, checks limits, calculates currency from matrix, awards directly to wallet\n8. Or click **Reject** → opens **Reject Modal** with reason text field → `bff_reject_activity_upload`\n9. Already-processed uploads open in read-only mode (no action buttons)\n\n### 4c. Common Admin Mistakes\n\n- Forgetting to set the primary dimension → matrix cannot render correctly\n- Setting required fields but leaving options empty → admin cannot select values during review\n- No matrix cells configured for a field combination → zero currency awarded on approval (not an error — just no matching price)\n- Approving without filling required fields → validation error returned\n- Configuring auto_populate fields with a `field_key` that doesn''t exist in the USER_PROFILE form → null values at upload time\n- No frequency limits configured → members can upload unlimited times", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/activity-based-earning.md#L77 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e990a2137f624a7dc0db8b92a9d577c34c49f341b83ea723e982c65e21645bde", "truncated": false}, "is_active": true}, {"id": "f9c84e6d-8b54-5340-b500-4f7661bf2dfe", "feature_slug": "activity-based-earning", "title": "Frequency Limits", "content": "### Configuration via transaction_limits\n\n**Reuses existing table** with `entity_type=''activity''`:\n\n```sql\n-- Example: Max 1 upload per user per day\nINSERT INTO transaction_limits (\n  merchant_id,\n  entity_type,\n  entity_id,        -- activity_master.id\n  scope,            -- ''user'' or ''total''\n  count,            -- Max uploads\n  time_unit,        -- ''day'', ''week'', ''month'', ''year''\n  time_value,       -- Usually 1\n  active_status\n) VALUES (\n  ''merchant-uuid'',\n  ''activity'',\n  ''exercise-activity-uuid'',\n  ''user'',\n  1,                -- 1 upload\n  ''day'',            -- per day\n  1,\n  true\n);\n```\n\n**Dual Validation:**\n1. **Upload time** - `upload_activity_image()` checks limits before creating record\n2. **Approval time** - `bff_approve_activity_upload()` re-checks limits (prevents race conditions)\n\n**Supported Patterns:**\n- ✅ Per user per day/week/month/year\n- ✅ Total (global) per period\n- ✅ Lifetime limits\n- ✅ Multiple limits per activity (e.g., 1/day AND 7/week AND 30/month)\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Activity_Based_Earning.md#L305 Frequency Limits", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9a598f7c9ea7b5e1c0bfcf550cd64a16cb71f6e8535a403fc14854b593595c66", "truncated": false}, "is_active": true}, {"id": "32d15a47-87d0-5e4e-8cb2-a36a16cfa245", "feature_slug": "activity-based-earning", "title": "Business Rules", "content": "### Core Rules\n\n1. **Field Validation**\n   - Required fields must be filled by admin\n   - Values must be in defined options list\n   - Validation at approval time (not upload time)\n\n2. **Currency Calculation**\n   - Matches `field_values` against `activity_currency_config`\n   - Primary dimension value must match `primary_value`\n   - Secondary field and value must match exactly\n   - Can award multiple currencies per upload (points + tickets)\n\n3. **Frequency Limits**\n   - Validated at upload (user-facing error)\n   - Re-validated at approval (admin-facing error)\n   - Counts both ''pending'' and ''approved'' uploads in window\n   - Prevents race conditions\n\n4. **Status Workflow**\n   - `pending` → User submitted, awaiting review\n   - `approved` → Admin approved, currency awarded\n   - `rejected` → Admin rejected, no currency\n   - `cancelled` → User cancelled before review\n\n5. **Direct Currency Award**\n   - Uses `post_wallet_transaction()` directly\n   - No CDC/Inngest needed for synchronous admin action\n   - Same pattern as `redeem_reward_with_points()`\n   - Atomic transaction: approval + currency award together\n   - Rollback if currency award fails\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Activity_Based_Earning.md#L898 Business Rules", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5a7d2fba6c616e7caf52c9a2e7752a6d7fc9d3837a0944a27a9acea687c724eb", "truncated": false}, "is_active": true}, {"id": "fcf7c3b7-0ed1-594c-ab1a-af2224b00bcd", "feature_slug": "activity-based-earning", "title": "7. Business Rules", "content": "**Rule:** Frequency limits are dual-validated — checked at upload time (member-facing) and re-checked at approval time (admin-facing, prevents race conditions where a second upload squeaks in before the first is approved).\n**Example:** Limit = 1/day. Member uploads at 9:00. Second upload at 9:01 is blocked. If admin somehow has two pending from a race condition, second approval fails.\n\n**Rule:** Frequency limit counting includes both `pending` and `approved` uploads in the window. Rejected and cancelled uploads do not count.\n**Example:** Limit = 3/week. Member has 2 approved + 1 pending this week = 3 total. Next upload is blocked.\n\n**Rule:** Currency is calculated by matching field values against `activity_currency_config`. The primary dimension value must match `primary_value`, and the secondary field/value must match exactly.\n**Example:** Field values: {time_of_day: \"morning\", exercise_type: \"yoga\"}. Primary dimension = time_of_day. Matches cell: primary_value=\"morning\", secondary_field=\"exercise_type\", secondary_value=\"yoga\" → 50 points.\n\n**Rule:** Multiple matrix tables (one per secondary field) can each contribute currency from a single upload. Awards are additive.\n**Example:** Exercise activity has two matrices: time × exercise_type (50 pts) and time × location (25 pts). Member''s upload matches both → 75 total points.\n\n**Rule:** Currency award uses `post_wallet_transaction()` directly — synchronous, atomic with the approval. If the wallet transaction fails, the entire approval rolls back.\n**Example:** Admin clicks Approve → field validation passes → matrix match found → wallet transaction attempted → if wallet error, upload stays `pending`.\n\n**Rule:** Field validation at approval time requires all `required` fields to have values, and manual field values must be in the defined options list.\n**Example:** exercise_type is required with options [yoga, running]. Admin submits \"dancing\" → validation error: \"invalid value, allowed: yoga, running.\"\n\n**Rule:** Auto-populated fields are fetched from the member''s USER_PROFILE form responses at upload time and stored in the ledger record. They are not re-fetched at approval time.\n**Example:** Member''s tier at upload time was \"Gold\". Even if they upgrade to \"Platinum\" before approval, the stored value remains \"Gold\".", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L219 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8a91f8cfdbf340f5f7823a4fde8fd739e912988fa182918925b638a5f372c06c", "truncated": false}, "is_active": true}, {"id": "c82aaa43-571b-5c4a-af14-cc7f0337e9fe", "feature_slug": "activity-based-earning", "title": "3. Configuration Reference", "content": "### Activity Setup\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Activity code | Unique identifier | `exercise` | Required |\n| Activity name | Display name | \"Exercise Activity\" | Required |\n| Description | Activity description | \"Upload your workout photo\" | Empty |\n| Icon URL | Activity icon | PNG/SVG URL | None |\n| Banner URLs | Banner images (array) | Multiple image URLs | Empty |\n| Active status | Whether activity accepts uploads | true | true |\n\n### Field Definitions\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Field key | Identifier used in matrix matching | `exercise_type` | Required |\n| Type | `manual` or `auto_populate` | `manual` | Required |\n| Label | Display name in admin form | \"Type of Exercise\" | Required |\n| Options | Allowed values (manual fields only) | [\"yoga\", \"running\", \"swimming\"] | Required for manual |\n| Field key source | USER_PROFILE form field (auto_populate only) | `membership_tier` | Required for auto_populate |\n| Required | Must be filled to approve | true | false |\n| Order | Display order in admin form | 1 | — |\n\n### Currency Matrix\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Primary dimension | Which field creates matrix columns | `time_of_day` | Required |\n| Primary value | Column value | \"morning\" | Per cell |\n| Secondary field | Which field creates matrix rows | `exercise_type` | Per matrix |\n| Secondary value | Row value | \"yoga\" | Per cell |\n| Points amount | Points to award for this combination | 50 | 0 |\n| Ticket type ID | Optional ticket type reference | UUID | null |\n| Ticket amount | Tickets to award | 2 | 0 |\n\n### Frequency Limits\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Scope | Who the limit applies to | `user` or `total` | — |\n| Time unit | Period of the limit | `day`, `week`, `month`, `year` | — |\n| Count | Maximum uploads in period | 1 | — |\n| Active status | Enable/disable this limit | true | true |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/activity-based-earning.md#L31 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "15ea19e5f160fff2406d214096267f5d7d4e59fa3fbed96715487bfb0d4597d0", "truncated": false}, "is_active": true}, {"id": "398486b9-9c5c-5ef5-a0b2-e650823ca823", "feature_slug": "activity-based-earning", "title": "Monitoring & Analytics", "content": "### Admin Dashboard Queries\n\n**Pending uploads count:**\n```sql\nSELECT COUNT(*) FROM activity_upload_ledger\nWHERE merchant_id = get_current_merchant_id()\n  AND status = ''pending'';\n```\n\n**Activity earnings report:**\n```sql\nSELECT \n  am.activity_name,\n  COUNT(DISTINCT aul.user_id) as unique_users,\n  COUNT(*) as total_uploads,\n  SUM(aul.points_awarded) as total_points,\n  SUM(aul.tickets_awarded) as total_tickets\nFROM activity_upload_ledger aul\nJOIN activity_master am ON aul.activity_id = am.id\nWHERE aul.merchant_id = get_current_merchant_id()\n  AND aul.status = ''approved''\n  AND aul.submitted_at >= NOW() - INTERVAL ''30 days''\nGROUP BY am.activity_name;\n```\n\n**User activity leaderboard:**\n```sql\nSELECT \n  ua.fullname,\n  COUNT(*) as upload_count,\n  SUM(aul.points_awarded) as total_points_earned\nFROM activity_upload_ledger aul\nJOIN user_accounts ua ON aul.user_id = ua.id\nWHERE aul.merchant_id = get_current_merchant_id()\n  AND aul.status = ''approved''\n  AND aul.submitted_at >= NOW() - INTERVAL ''7 days''\nGROUP BY ua.id, ua.fullname\nORDER BY total_points_earned DESC\nLIMIT 10;\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Activity_Based_Earning.md#L1139 Monitoring & Analytics", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "71a8d787bf60e272b8084843b4943fab2384ed3e2e13bfdc21814f6dfad76b19", "truncated": false}, "is_active": true}, {"id": "2e94a324-4ab1-573b-bd59-c77e8ea7f082", "feature_slug": "activity-based-earning", "title": "Database Schema", "content": "### Table 1: activity_master\n\n**Purpose:** Defines activity types with dynamic field configurations\n\n| Column | Type | Description |\n|--------|------|-------------|\n| `id` | UUID | Primary key |\n| `merchant_id` | UUID | Merchant ownership |\n| `activity_code` | VARCHAR(50) | Unique code (e.g., ''exercise'', ''meditation'') |\n| `activity_name` | TEXT | Display name |\n| `description` | TEXT | Activity description |\n| `field_definitions` | JSONB | Dynamic field configs (see structure below) |\n| `primary_dimension` | TEXT | Which field is primary grouping |\n| `icon_url` | TEXT | Activity icon |\n| `banner_urls` | TEXT[] | Banner images |\n| `active_status` | BOOLEAN | Active flag |\n\n**field_definitions JSONB Structure:**\n\n**Manual Fields (Admin selects from options):**\n```json\n{\n  \"exercise_type\": {\n    \"type\": \"manual\",\n    \"label\": \"Type of Exercise\",\n    \"options\": [\"yoga\", \"running\", \"swimming\", \"cycling\"],\n    \"required\": true,\n    \"order\": 1\n  },\n  \"time_of_day\": {\n    \"type\": \"manual\",\n    \"label\": \"Time\",\n    \"options\": [\"morning\", \"afternoon\", \"evening\"],\n    \"required\": true,\n    \"order\": 2\n  }\n}\n```\n\n**Auto-Populated Fields (Pulled from USER_PROFILE form):**\n```json\n{\n  \"user_tier\": {\n    \"type\": \"auto_populate\",\n    \"label\": \"User Tier\",\n    \"field_key\": \"membership_tier\",\n    \"required\": true,\n    \"order\": 3\n  },\n  \"user_outlet\": {\n    \"type\": \"auto_populate\",\n    \"label\": \"User Branch\",\n    \"field_key\": \"preferred_outlet\",\n    \"required\": false,\n    \"order\": 4\n  }\n}\n```\n\n**Field Type Properties:**\n\n| Property | Type: `manual` | Type: `auto_populate` |\n|----------|----------------|------------------------|\n| `type` | Free text (flexible) | Free text (flexible) |\n| `label` | Display name | Display name |\n| `options` | Array of dropdown values | Not used |\n| `field_key` | Not used | Field key from USER_PROFILE form |\n| `required` | true/false | true/false |\n| `order` | Display order | Display order |\n\n**Notes:**\n- `type` is free text string (not enum) for future extensibility\n- Auto-populated fields always pull from USER_PROFILE form (no source field needed)\n- Values are fetched from `form_responses` table via `field_key` mapping\n- Auto-populated at upload time, stored in `activity_upload_ledger.field_values`\n\n**📄 See detailed implementation:** [Activity_Auto_Populate_Fields.md](./Activity_Auto_Populate_Fields.md)\n\n---\n\n### Table 2: activity_currency_config\n\n**Purpose:** Currency awards for field combinations (matrix cells)\n\n| Column | Type | Description |\n|--------|------|-------------|\n| `id` | UUID | Primary key |\n| `merchant_id` | UUID | Merchant ownership |\n| `activity_id` | UUID | References activity_master |\n| `primary_value` | TEXT | Value from primary dimension (e.g., ''morning'') |\n| `secondary_field` | TEXT | Which secondary field (e.g., ''exercise_type'') |\n| `secondary_value` | TEXT | Value from secondary field (e.g., ''yoga'') |\n| `points_amount` | NUMERIC | Points to award |\n| `ticket_type_id` | UUID | Optional ticket type reference |\n| `ticket_amount` | NUMERIC | Tickets to award |\n| `active_status` | BOOLEAN | Active flag |\n\n**Example Records:**\n```sql\n-- Matrix 1: time × exercise_type\n{primary_value: ''morning'', secondary_field: ''exercise_type'', secondary_value: ''yoga''} → 50 points\n{primary_value: ''morning'', secondary_field: ''exercise_type'', secondary_value: ''running''} → 60 points\n{primary_value: ''evening'', secondary_field: ''exercise_type'', secondary_value: ''yoga''} → 40 points\n\n-- Matrix 2: time × location  \n{primary_value: ''morning'', secondary_field: ''location'', secondary_value: ''central''} → 30 points + 2 raffle tickets\n{primary_value: ''evening'', secondary_field: ''location'', secondary_value: ''central''} → 25 points + 1 raffle ticket\n```\n\n**Unique Constraint:** `(activity_id, primary_value, secondary_field, secondary_value)`\n\n---\n\n### Table 3: activity_upload_ledger\n\n**Purpose:** User submissions with approval workflow\n\n| Column | Type | Description |\n|--------|------|-------------|\n| `id` | UUID | Primary key |\n| `merchant_id` | UUID | Merchant ownership |\n| `user_id` | UUID | Submitter |\n| `activity_id` | UUID | Activity type |\n| `image_url` | TEXT | Uploaded image |\n| `field_values` | JSONB | Admin-filled values |\n| `status` | TEXT | pending/approved/rejected/cancelled |\n| `submitted_at` | TIMESTAMPTZ | Upload time |\n| `approved_at` | TIMESTAMPTZ | Approval time |\n| `approved_by` | UUID | Admin who approved |\n| `rejected_by` | UUID | Admin who rejected |\n| `rejection_reason` | TEXT | Rejection explanation |\n| `currency_processed_at` | TIMESTAMPTZ | When currency awarded |\n| `currency_error` | TEXT | Error if award failed |\n| `points_awarded` | NUMERIC | Points given (snapshot) |\n| `tickets_awarded` | NUMERIC | Tickets given (snapshot) |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Activity_Based_Earning.md#L78 Database Schema", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e486a5b791600d81d2d9b759261a6aa8f6599cd4e467679edf3a921c4e955aed", "truncated": false}, "is_active": true}, {"id": "2a8ff077-1b95-5851-9212-e3e24f8bf12c", "feature_slug": "activity-based-earning", "title": "2. Key Concepts", "content": "**Activity** — A merchant-defined activity type that members can submit uploads for. Identified by a unique code (e.g., `exercise`, `posm_check`). Each activity defines its own field definitions, primary dimension, and currency matrix. Example: \"Exercise Activity\" with fields for exercise type, time of day, and location.\n\n**Field Definition** — A configurable field attached to an activity. Two types exist:\n- `manual` — Admin selects a value from predefined options during review. Example: exercise_type with options [yoga, running, swimming].\n- `auto_populate` — Value pulled automatically from the member''s USER_PROFILE form data at upload time. Example: user_tier pulled from the member''s membership_tier field.\n\n**Primary Dimension** — The field whose values become columns in the currency matrix. Only one field per activity serves as the primary dimension. Example: if `time_of_day` is primary, columns are \"morning\", \"afternoon\", \"evening\".\n\n**Secondary Field** — Any non-primary field that creates rows in the matrix. Multiple secondary fields produce multiple matrix tables for the same activity. Example: `exercise_type` as secondary creates one matrix; `location` as secondary creates another.\n\n**Currency Matrix** — A 2D pricing grid: primary dimension values × secondary field values → currency amounts. Each cell defines points and/or tickets to award. Example: morning × yoga = 50 points; evening × running = 55 points + 2 raffle tickets.\n\n**Upload Ledger** — The record of a member''s activity submission, tracking the uploaded image, status, field values (filled by admin), and currency awarded. One record per upload.\n\n**Status** — The lifecycle state of an upload: `pending` (submitted, awaiting review), `approved` (admin approved, currency awarded), `rejected` (admin rejected, no currency), `cancelled` (member cancelled before review).\n\n**Frequency Limit** — A cap on how many uploads a member (or all members globally) can submit within a time window. Reuses the platform''s `transaction_limits` table with `entity_type=''activity''`. Multiple limits can stack (e.g., 1/day AND 7/week AND 30/month).", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0aae9cb7ecdfcdcf6013b699b8b68761f6ab5f3c64d6da9a26d9aaf4881b779d", "truncated": false}, "is_active": true}, {"id": "6defde54-724b-56b4-94e6-6eb0186595e9", "feature_slug": "activity-based-earning", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Activity uploads let your members earn points by proving they did something — exercise, store visits, POSM compliance checks. They upload a photo, your team reviews it, and points are awarded automatically based on what they did.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member says upload was rejected\" | Check the rejection reason in the review modal — admin provides a reason when rejecting. Member should re-upload with correct proof. |\n| \"Member can''t upload — says limit reached\" | Frequency limits are active. Check `transaction_limits` for this activity — shows max uploads per period and when the next window opens. |\n| \"Upload approved but no points received\" | Check `currency_error` on the upload ledger record. If the matrix has no matching cell for the field values selected, zero points are awarded — not an error, but a configuration gap. |\n| \"How long until my upload is reviewed?\" | No SLA — depends on admin review queue. Check pending count in the Activity Uploads page. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L153 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e1ce61a6bf1c26ed88ec5dfc365fabc6665c04bb0fb6e3d3921b32b50112a3ec", "truncated": false}, "is_active": true}, {"id": "e2e7ca8d-afcb-5c7a-9327-8d3233def03f", "feature_slug": "activity-based-earning", "title": "1. Overview", "content": "Activity-Based Earning is an image-upload-based earning mechanism where members submit proof photos of completed activities (exercise, POSM checks, volunteer work) and earn currency upon admin approval. Unlike purchase-based earning which processes transactions automatically, this feature requires human review — a member uploads an image, an admin classifies the submission by selecting field values, and the system calculates the currency award from a pre-configured pricing matrix.\n\nThe pricing matrix is the core concept: merchants define a two-dimensional grid where one axis (the primary dimension) crosses with one or more secondary fields to produce specific currency amounts. For example, an exercise activity might award different points for \"yoga in the morning\" (50 pts) versus \"running in the evening\" (45 pts). This lets merchants incentivize specific combinations of activity attributes without building custom logic for each one.\n\nKey characteristics: (1) **matrix-based pricing** — a 2D grid of primary × secondary values determines exact currency amounts per combination; (2) **dual-validated frequency limits** — checked at both upload time and approval time to prevent race conditions; (3) **synchronous currency award** — admin approval immediately deposits currency into the member''s wallet (no async queue); (4) **dynamic field definitions** — each activity defines its own set of fields that admins fill during review, including auto-populated fields pulled from the member''s profile.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6508b3dfac879667078b9ba88168d21d0424f822a738cc43010585d37486afb8", "truncated": false}, "is_active": true}, {"id": "60e5ea30-298a-5a22-9a26-a645803441af", "feature_slug": "activity-based-earning", "title": "8. Related Features", "content": "| Feature | Connection to Activity-Based Earning |\n|---|---|\n| Currency | Points/tickets awarded via `post_wallet_transaction()` with `source_type=''activity''`. See `Currency.md`. |\n| Mission | Missions can track \"activity upload approved\" as a progress event. See `Mission.md`. |\n| Transaction Limits | Reuses `transaction_limits` table with `entity_type=''activity''` for frequency caps. See `Purchase_Transaction.md`. |\n| Forms | Auto-populate fields pull values from USER_PROFILE form responses. See `Forms.md`. |\n| Earn Channels | Activity upload appears as an earn channel in the member app. See earn channel configuration. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L242 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "509629ced45bed17f36d128a25436d88e140b43352af550fa280c9873daae314", "truncated": false}, "is_active": true}, {"id": "5c9b82de-ea69-5342-9048-52c1c99dae37", "feature_slug": "activity-based-earning", "title": "Frontend Integration Patterns", "content": "### User Upload Flow (Customer App)\n\n```javascript\n// Check user can upload (optional - backend validates anyway)\nconst canUpload = await checkUploadAvailable(activityId);\n\n// Upload image to storage\nconst imageUrl = await uploadToSupabaseStorage(file);\n\n// Submit activity\nconst { data } = await supabase.rpc(''upload_activity_image'', {\n  p_activity_id: activityId,\n  p_image_url: imageUrl\n});\n\nif (data.success) {\n  showToast(data.title, data.description, ''success'');\n} else {\n  showToast(data.title, data.description, ''error'');\n  // Show next_available_at from data if limit exceeded\n}\n```\n\n---\n\n### Admin Approval Flow (Admin UI)\n\n```javascript\n// Get pending uploads\nconst { data } = await supabase.rpc(''bff_get_activity_uploads'', {\n  p_status_filter: ''pending'',\n  p_limit: 50,\n  p_offset: 0\n});\n\nconst pendingUploads = data.data.uploads;\n\n// Admin selects upload, fills in field values\nconst fieldValues = {\n  exercise_type: ''yoga'',\n  time_of_day: ''morning'',\n  location: ''central''\n};\n\n// Approve with field values\nconst result = await supabase.rpc(''bff_approve_activity_upload'', {\n  p_upload_id: selectedUpload.upload_id,\n  p_field_values: fieldValues\n});\n\nif (result.success) {\n  showToast(\n    result.title, \n    `Awarded ${result.data.points_awarded} points`,\n    ''success''\n  );\n  refreshPendingList();\n} else {\n  showToast(result.title, result.description, ''error'');\n}\n```\n\n---\n\n### Matrix Configuration Flow (Admin UI)\n\n```javascript\n// Fetch current matrix\nconst { data } = await supabase.rpc(''bff_get_activity_matrix'', {\n  p_activity_id: activityId\n});\n\nconst fieldDefs = data.data.field_definitions;\nconst matrix = data.data.matrix;\nconst primaryDim = data.data.primary_dimension;\n\n// Render matrix table\n// Rows: primary_dimension values (morning, evening)\n// Columns: secondary field values (yoga, running, swimming)\nconst primaryValues = [...new Set(matrix.map(m => m.primary_value))];\nconst secondaryField = ''exercise_type''; // Can switch between fields\nconst secondaryValues = fieldDefs[secondaryField].options;\n\n// Build grid\nconst grid = {};\nprimaryValues.forEach(pv => {\n  grid[pv] = {};\n  secondaryValues.forEach(sv => {\n    const cell = matrix.find(m => \n      m.primary_value === pv && \n      m.secondary_field === secondaryField &&\n      m.secondary_value === sv\n    );\n    grid[pv][sv] = cell || { points_amount: 0 };\n  });\n});\n\n// Admin edits cells\ngrid[''morning''][''yoga''].points_amount = 55;\n\n// Convert back to array for save\nconst matrixArray = [];\nObject.entries(grid).forEach(([primary, secondaries]) => {\n  Object.entries(secondaries).forEach(([secondary, config]) => {\n    matrixArray.push({\n      id: config.id, // Include ID for update, omit for create\n      primary_value: primary,\n      secondary_field: secondaryField,\n      secondary_value: secondary,\n      points_amount: config.points_amount,\n      ticket_type_id: config.ticket_type_id,\n      ticket_amount: config.ticket_amount || 0\n    });\n  });\n});\n\n// Save matrix\nawait supabase.rpc(''bff_upsert_activity_currency_matrix'', {\n  p_activity_id: activityId,\n  p_matrix_configs: matrixArray\n});\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Activity_Based_Earning.md#L1012 Frontend Integration Patterns", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "84f0e3aa225d8fbb876dcaf8bf07243a971e0f5e7ea530cd9e53590f776d1944", "truncated": false}, "is_active": true}, {"id": "32f5e7f7-42c0-5a42-bad0-f90b7312b383", "feature_slug": "activity-based-earning", "title": "wallet_ledger Integration", "content": "### Complete Source Tracking\n\nWhen `bff_approve_activity_upload()` awards currency, it creates `wallet_ledger` entries with **full audit trail**:\n\n```json\n{\n  \"id\": \"ledger-uuid\",\n  \"user_id\": \"user-uuid\",\n  \"merchant_id\": \"merchant-uuid\",\n  \"currency\": \"points\",\n  \"transaction_type\": \"earn\",\n  \"component\": \"base\",\n  \"amount\": 50,\n  \"signed_amount\": 50,\n  \"source_type\": \"activity\",           ← Added to enum\n  \"source_id\": \"upload-uuid\",          ← Links to activity_upload_ledger.id\n  \"target_entity_id\": null,            ← NULL for points, ticket_type_id for tickets\n  \"balance_before\": 100,\n  \"balance_after\": 150,\n  \"metadata\": {                        ← Full context\n    \"activity_id\": \"exercise-uuid\",\n    \"activity_name\": \"Exercise Activity\",\n    \"activity_code\": \"exercise\",\n    \"field_values\": {\n      \"exercise_type\": \"yoga\",\n      \"time_of_day\": \"morning\",\n      \"location\": \"central\"\n    },\n    \"matrix_match\": {\n      \"primary_dimension\": \"time_of_day\",\n      \"primary_value\": \"morning\",\n      \"secondary_field\": \"exercise_type\",\n      \"secondary_value\": \"yoga\"\n    },\n    \"approved_by\": \"admin-uuid\",\n    \"approved_at\": \"2026-01-22T14:30:00Z\",\n    \"image_url\": \"https://storage.../image.jpg\"\n  },\n  \"description\": \"Activity: exercise-uuid\",\n  \"expiry_date\": \"2026-07-22\",         ← Calculated by post_wallet_transaction\n  \"deductible_balance\": 50,\n  \"created_at\": \"2026-01-22T14:30:00Z\"\n}\n```\n\n### Audit Trail Capabilities\n\n**Query all activity earnings:**\n```sql\nSELECT * FROM wallet_ledger \nWHERE source_type = ''activity''\n  AND merchant_id = get_current_merchant_id();\n```\n\n**Trace specific upload:**\n```sql\nSELECT \n  wl.*,\n  aul.image_url,\n  aul.field_values,\n  am.activity_name\nFROM wallet_ledger wl\nJOIN activity_upload_ledger aul ON wl.source_id = aul.id\nJOIN activity_master am ON aul.activity_id = am.id\nWHERE wl.source_id = ''specific-upload-uuid'';\n```\n\n**User activity earning history:**\n```sql\nSELECT \n  aul.submitted_at,\n  am.activity_name,\n  aul.field_values,\n  aul.points_awarded,\n  wl.balance_after\nFROM activity_upload_ledger aul\nJOIN activity_master am ON aul.activity_id = am.id\nLEFT JOIN wallet_ledger wl ON wl.source_id = aul.id AND wl.source_type = ''activity''\nWHERE aul.user_id = ''user-uuid''\n  AND aul.status = ''approved''\nORDER BY aul.submitted_at DESC;\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Activity_Based_Earning.md#L218 wallet_ledger Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "abf316b8c4bac2aff19632d4e5d2ba6954f770ab300ef270c9d2f18b6ba29875", "truncated": false}, "is_active": true}, {"id": "bf154780-c542-5677-b73a-2ff46f55f021", "feature_slug": "activity-based-earning", "title": "System Architecture", "content": "### Data Flow\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│  User Upload Flow                                                │\n├─────────────────────────────────────────────────────────────────┤\n│                                                                  │\n│  User uploads image                                              │\n│         ↓                                                        │\n│  upload_activity_image()                                         │\n│         ↓                                                        │\n│  Check frequency limits (fn_check_activity_upload_limits)       │\n│         ↓                                                        │\n│  Create activity_upload_ledger (status=''pending'')               │\n│         ↓                                                        │\n│  Return success to user                                          │\n│                                                                  │\n└─────────────────────────────────────────────────────────────────┘\n\n┌─────────────────────────────────────────────────────────────────┐\n│  Admin Approval Flow                                             │\n├─────────────────────────────────────────────────────────────────┤\n│                                                                  │\n│  Admin reviews image                                             │\n│         ↓                                                        │\n│  Admin fills field values (exercise_type: yoga, time: morning)  │\n│         ↓                                                        │\n│  bff_approve_activity_upload(upload_id, field_values)           │\n│         ↓                                                        │\n│  Validate field values (fn_validate_activity_field_values)      │\n│         ↓                                                        │\n│  Re-check limits (race condition protection)                    │\n│         ↓                                                        │\n│  Calculate currency (fn_calculate_activity_currency)            │\n│    - Match field_values to activity_currency_config             │\n│    - Find matching primary_value + secondary_value combos       │\n│         ↓                                                        │\n│  Award currency DIRECTLY (post_wallet_transaction)              │\n│    - source_type: ''activity''                                    │\n│    - source_id: upload_id                                       │\n│    - component: ''base''                                          │\n│    - metadata: full audit trail                                 │\n│         ↓                                                        │\n│  Update upload status=''approved''                                │\n│         ↓                                                        │\n│  Return success with currency amounts                           │\n│                                                                  │\n└─────────────────────────────────────────────────────────────────┘\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Activity_Based_Earning.md#L24 System Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5d72d16836679d32756b5f3a025bdee65ca86926f1dac1e400849c135fd57597", "truncated": false}, "is_active": true}, {"id": "d808198a-6731-57f8-808a-580cef9fbde2", "feature_slug": "activity-based-earning", "title": "WeWeb Data Grid Integration", "content": "### Load Activity Configuration\n\n```javascript\n// Single RPC call\nconst response = await supabase.rpc(''api_get_activity_full'', {\n  p_activity_id: ''activity-uuid'',\n  p_mode: ''edit''\n});\n\n// Response structure\nconst columns = response.columns;          // Shared columns\nconst config = response.config;            // Activity config\nconst matrices = response.config.matrices; // Array of pivot tables\n```\n\n### Bind to Repeater with Grids\n\n**Repeater Setup:**\n- **Data source:** `response.config.matrices`\n- **Item variable:** `matrix`\n\n**Inside Each Repeater Item:**\n\n**1. Matrix Label/Heading:**\n```javascript\nheading.text = matrix.label;  // \"Check Type\", \"Exercise Type\", etc.\n```\n\n**2. Data Grid Binding:**\n```javascript\n// Columns (same for all grids - bind from parent context)\ndataGrid.columns = response.columns;\n\n// Data (different per matrix)\ndataGrid.data = matrix.data;\n```\n\n### Handle Cell Edits\n\n**On Cell Value Changed Event:**\n\n```javascript\n// Calculate row index\nconst matrixIndex = context.item.index;  // From repeater\n\nconst rowIndex = variables[''your-variable-id'']\n  .config\n  .matrices[matrixIndex]\n  .data\n  .findIndex(row => row.secondary_value === event.row.secondary_value);\n\n// Update entire row\nconst updatedRow = {\n  ...event.row,\n  [event.columnId]: event.newValue\n};\n\n// Execute edit action\nexecuteAction({\n  action: ''edit'',\n  group: ''matrices'',\n  index: matrixIndex,\n  nested_field: ''data'',\n  nested_index: rowIndex,\n  value: updatedRow\n});\n```\n\n**What This Does:**\n- Finds which row was edited (by matching `secondary_value`)\n- Updates the changed field in the row object\n- Replaces entire row in state (LEVEL 3.5 edit pattern)\n- Triggers 3-second debounced save\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Activity_Based_Earning.md#L934 WeWeb Data Grid Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "56f61a8c175b1bd80d8e39c4b51ec4917e176cf2f1f9c9054453c440938c6979", "truncated": false}, "is_active": true}, {"id": "dd7dbaca-38f1-5301-aa91-45eca023dc12", "feature_slug": "activity-based-earning", "title": "Activity Earning Domain Reference", "content": "**Keywords:** activity, upload, image upload, admin approval, exercise, POSM, activity matrix, field definitions, primary dimension, secondary field, currency config, frequency limit\n**Source:** `Activity_Based_Earning.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `upload_activity_image(p_activity_id, p_image_url)` | `p_activity_id (uuid)`, `p_image_url (text)` | Success/limit-exceeded with upload_id | 411–450 |\n| `bff_approve_activity_upload(p_upload_id, p_field_values)` | `p_upload_id (uuid)`, `p_field_values (jsonb)` | Points/tickets awarded, field values | 454–510 |\n| `bff_get_activity_uploads(p_status_filter, p_activity_id, p_limit, p_offset)` | Status filter, activity ID, pagination | Upload list with user info | 514–557 |\n| `bff_get_activity_matrix(p_activity_id)` | `p_activity_id (uuid)` | Matrix config, field definitions, pivot data | 560–635 |\n| `api_get_activity_full(p_activity_id, p_mode)` | `p_activity_id (uuid)`, `p_mode (text)` | Columns + config with matrices array for Data Grid | 348–406 |\n| `bff_upsert_activity_currency_matrix(p_activity_id, p_matrix_configs)` | `p_activity_id (uuid)`, `p_matrix_configs (jsonb[])` | Created/updated/deleted counts | 639–690 |\n**Key Business Rules (summary):**\n- Users upload images; admins review, fill field values, and approve → currency awarded directly\n- Currency calculation: match `field_values` against `activity_currency_config` matrix (primary × secondary)\n- Status workflow: `pending` → `approved` / `rejected` / `cancelled`\n- Frequency limits checked at both upload time and approval time (race condition protection)\n- Direct `post_wallet_transaction()` call (no CDC needed — synchronous admin action)", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/activity-earning.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e951aa5a7544789e0bde54c996bf35eb96ed6766acd03e7eb8b90675d49256c9", "truncated": false}, "is_active": true}, {"id": "64d12851-2622-59fd-ad71-4255900b76b6", "feature_slug": "activity-based-earning", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Limit: 1/user/day, member already uploaded today | Upload blocked with \"limit reached\" + next_available_at |\n| Limit: 1/user/day, upload pending, member tries again | Upload blocked — pending uploads count toward limits |\n| No matrix cell for selected field combination | Approval succeeds with 0 points awarded |\n| Required field left empty by admin | Approval fails with validation error listing missing fields |\n| Invalid option value for manual field | Approval fails with validation error listing invalid values + allowed options |\n| Activity `active_status = false` | Uploads blocked |\n| Auto_populate field with no profile data | Field value is null — handled based on required flag |\n\n**Business rules as assertions:**\n\n- ASSERT: Upload creates ledger record with `status=''pending''`, `field_values=null`\n- ASSERT: Frequency limit counts both `pending` and `approved` uploads in the time window\n- ASSERT: Frequency limit is re-checked at approval time (not just upload time)\n- ASSERT: On approval, `post_wallet_transaction` creates wallet_ledger entries with `source_type=''activity''` and `source_id=upload_id`\n- ASSERT: Points + tickets can both be awarded from a single matrix cell\n- ASSERT: Multiple matrix tables (one per secondary field) can each award currency from the same upload\n- ASSERT: Rejected upload records `rejected_by` and `rejection_reason`\n- ASSERT: Approved upload records `approved_by`, `approved_at`, `points_awarded`, `tickets_awarded`\n- ASSERT: Currency award is atomic with approval — if wallet transaction fails, approval rolls back\n\n**Status model (single track):**\n\n| Field | Values | Transition | Meaning |\n|---|---|---|---|\n| `status` | `pending` | → `approved` | Admin approved, currency awarded |\n| `status` | `pending` | → `rejected` | Admin rejected, no currency |\n| `status` | `pending` | → `cancelled` | Member cancelled before review |\n\n- No transitions from `approved`, `rejected`, or `cancelled` — these are terminal states\n- Currency is only awarded on the `pending → approved` transition", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L153 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e2e7d9dbaf914b39a32eccbe70c7e4e4e60f275599b0ac74e4fbfed792f03eba", "truncated": false}, "is_active": true}, {"id": "279f0274-716c-57f6-804e-bfa2dc8a734f", "feature_slug": "activity-based-earning", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| Earn Drawer | Bottom-sheet from Homepage | `bff_get_earn_channels()` |\n| Activity Upload | Within Earn Drawer | `upload_activity_image(p_activity_id, p_image_url)` |\n| History Drawer | Bottom-sheet from Homepage/Profile | `bff_get_campaign_history(p_filter=''activity'')` |\n\n### 5a. Upload an Activity Image\n\n1. Member opens the **Earn Drawer** and selects the activity earn channel\n2. Member takes or selects a photo and uploads to Supabase Storage\n3. App calls `upload_activity_image` with the activity ID and image URL\n4. Backend checks frequency limits — if exceeded, returns error with `next_available_at` timestamp\n5. On success: upload ledger record created with `status=''pending''`, member sees confirmation message (\"Your submission is pending admin approval\")\n\n### 5b. View Upload History\n\n1. Member opens **History Drawer** → selects **Campaigns** tab → **Activity** sub-filter chip\n2. Each row shows: activity name, submission date, status, points/tickets awarded (if approved)\n3. Statuses displayed: Pending, Approved, Rejected", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/activity-based-earning.md#L127 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8f6027626e6fe2f579ab0de48289cb8380fd6d01f3ef8cee265d51e39479321d", "truncated": false}, "is_active": true}, {"id": "73371f0b-aa09-5ba7-a0e0-d0d6f125cd24", "feature_slug": "activity-based-earning", "title": "6b. For Marketing", "content": "**Value proposition:** Activity-Based Earning turns real-world actions into loyalty engagement. Instead of only earning from purchases, members earn by doing things the brand wants to encourage — exercising, visiting stores, verifying product displays. The matrix-based pricing lets merchants fine-tune incentives per combination (morning yoga earns more than evening yoga) without custom development.\n\n**Use-case stories:**\n\n1. **Fitness brand** — Creates an \"Exercise\" activity with time × exercise type matrix. Morning workouts earn more points than evening ones, incentivizing early activity. Members upload gym selfies or fitness tracker screenshots. Multiple limits (1/day, 7/week) encourage daily habits without bulk gaming.\n\n2. **CPG distributor (POSM)** — Creates a \"POSM Check\" activity where field reps upload photos of in-store displays. Matrix prices by display size (S/M/L) × check type (planogram compliance vs. POSM presence). Larger displays and correct planograms earn more. Monthly upload limit matches the visit cadence.\n\n3. **Wellness campaign** — Combines activity earning with missions. Mission tracks \"3 approved exercise uploads this week\" as a completion condition. Activity points stack on top of mission completion rewards, creating a double-incentive loop.\n\n**Metrics merchants care about:** uploads per day, approval rate, average time-to-review, total currency awarded by activity type, top uploading members, matrix cell utilization (which combinations are most common).", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/activity-based-earning.md#L153 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "activity-based-earning", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4d2473996505a71702da3140c253b8cbdac6df70b3e0f8e7603ee50738a9313f", "truncated": false}, "is_active": true}, {"id": "cdce6d81-5604-59ab-9fb7-da40a4246a2c", "feature_slug": "admin-panel", "title": "Business Rules", "content": "1. A user''s sidebar is the intersection of: `admin_role_permissions` (resource access) AND NOT `hidden_menu_categories/hidden_menu_items` (role config exclusions). Both filters apply server-side in `bff_get_admin_menu()`.\n2. `settings` category is never hidden by `hidden_menu_categories` — it is admin infrastructure. Individual settings items can still be hidden via `hidden_menu_items`.\n3. `default_path` redirect fires once per login session. FE must guard against repeated redirects (sessionStorage flag or auth store flag).\n4. Floating menu appears only when `floating_menu` array is non-empty. It overlays at the bottom regardless of sidebar state. When present and sidebar is visible, FE must add bottom padding to prevent content being obscured.\n5. `hide_sidebar = true` removes the sidebar entirely — content expands to full width. Used for frontline roles that only need the floating menu.\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Admin_Panel.md#L284 Business Rules", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "admin-panel", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6c7334634102c91709b218e23a8b8f7168be70bc14bedff155790bb0688e5acf", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
